import { createContext, useContext, useReducer } from "react";

// ─── Initial State ───────────────────────────────────────────────────────────
const initialState = {
  user: null,
  token: null,
  isAuthenticated: false,
  isLoading: false,
  error: null,
};

// ─── Action Types ────────────────────────────────────────────────────────────
export const AUTH_ACTIONS = {
  AUTH_START: "AUTH_START",
  AUTH_SUCCESS: "AUTH_SUCCESS",
  AUTH_FAILURE: "AUTH_FAILURE",
  LOGOUT: "LOGOUT",
  CLEAR_ERROR: "CLEAR_ERROR",
};

// ─── Reducer ─────────────────────────────────────────────────────────────────
function authReducer(state, action) {
  switch (action.type) {
    case AUTH_ACTIONS.AUTH_START:
      return { ...state, isLoading: true, error: null };

    case AUTH_ACTIONS.AUTH_SUCCESS:
      return {
        ...state,
        isLoading: false,
        isAuthenticated: true,
        user: action.payload.user,
        token: action.payload.token,
        error: null,
      };

    case AUTH_ACTIONS.AUTH_FAILURE:
      return {
        ...state,
        isLoading: false,
        isAuthenticated: false,
        user: null,
        token: null,
        error: action.payload,
      };

    case AUTH_ACTIONS.LOGOUT:
      return { ...initialState };

    case AUTH_ACTIONS.CLEAR_ERROR:
      return { ...state, error: null };

    default:
      return state;
  }
}

// ─── Context ─────────────────────────────────────────────────────────────────
const AuthContext = createContext(null);

// ─── Provider ────────────────────────────────────────────────────────────────
export function AuthProvider({ children }) {
  const [state, dispatch] = useReducer(authReducer, initialState);

  /** Mock signup — replace with real API call */
  async function signup({ username, email, password }) {
    dispatch({ type: AUTH_ACTIONS.AUTH_START });
    try {
      // Simulate network delay
      await new Promise((res) => setTimeout(res, 800));

      // Mock validation
      if (!username || !email || !password) throw new Error("All fields required.");

      const mockUser = { id: Date.now(), username, email, role: "customer" };
      const mockToken = `mock-token-${Date.now()}`;

      dispatch({
        type: AUTH_ACTIONS.AUTH_SUCCESS,
        payload: { user: mockUser, token: mockToken },
      });

      return { success: true };
    } catch (err) {
      dispatch({ type: AUTH_ACTIONS.AUTH_FAILURE, payload: err.message });
      return { success: false, error: err.message };
    }
  }

  /** Mock login — replace with real API call */
  async function login({ email, password }) {
    dispatch({ type: AUTH_ACTIONS.AUTH_START });
    try {
      await new Promise((res) => setTimeout(res, 800));

      if (!email || !password) throw new Error("Email and password required.");

      // Mock: any credentials pass
      const mockUser = { id: 1, username: "zawadi", email, role: "customer" };
      const mockToken = `mock-token-${Date.now()}`;

      dispatch({
        type: AUTH_ACTIONS.AUTH_SUCCESS,
        payload: { user: mockUser, token: mockToken },
      });

      return { success: true };
    } catch (err) {
      dispatch({ type: AUTH_ACTIONS.AUTH_FAILURE, payload: err.message });
      return { success: false, error: err.message };
    }
  }

  function logout() {
    dispatch({ type: AUTH_ACTIONS.LOGOUT });
  }

  function clearError() {
    dispatch({ type: AUTH_ACTIONS.CLEAR_ERROR });
  }

  return (
    <AuthContext.Provider value={{ ...state, signup, login, logout, clearError }}>
      {children}
    </AuthContext.Provider>
  );
}

// ─── Hook ─────────────────────────────────────────────────────────────────────
export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside <AuthProvider>");
  return ctx;
}

/* ── Auth shared styles ───────────────────────────────────── */
:root {
  --mealy-orange: #f97316;
  --mealy-orange-hover: #ea6c0a;
  --mealy-bg: #fafaf9;
  --mealy-card-bg: #ffffff;
  --mealy-border: #e7e5e4;
  --mealy-text: #1c1917;
  --mealy-muted: #78716c;
  --mealy-error: #dc2626;
  --mealy-error-bg: #fef2f2;
  --mealy-radius: 12px;
  --mealy-shadow: 0 4px 24px rgba(0, 0, 0, 0.08);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Inter", "Segoe UI", sans-serif;
  background-color: var(--mealy-bg);
  color: var(--mealy-text);
}

/* ── Auth page wrapper ────────────────────────────────────── */
.auth-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

/* ── Card ─────────────────────────────────────────────────── */
.auth-card {
  background: var(--mealy-card-bg);
  border: 1px solid var(--mealy-border);
  border-radius: var(--mealy-radius);
  box-shadow: var(--mealy-shadow);
  padding: 40px 36px;
  width: 100%;
  max-width: 440px;
}

/* ── Logo ─────────────────────────────────────────────────── */
.auth-logo {
  display: flex;
  justify-content: center;
  margin-bottom: 28px;
}

.auth-logo img {
  height: 48px;
  width: auto;
}

/* ── Heading ──────────────────────────────────────────────── */
.auth-heading {
  font-size: 1.5rem;
  font-weight: 700;
  text-align: center;
  margin-bottom: 6px;
}

.auth-subtext {
  font-size: 0.9rem;
  color: var(--mealy-muted);
  text-align: center;
  margin-bottom: 28px;
}

/* ── Form ─────────────────────────────────────────────────── */
.auth-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.auth-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.auth-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.auth-field label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--mealy-text);
}

/* ── Inputs ───────────────────────────────────────────────── */
.input-primary {
  width: 100%;
  padding: 10px 14px;
  border: 1.5px solid var(--mealy-border);
  border-radius: 8px;
  font-size: 0.9rem;
  background: #fff;
  color: var(--mealy-text);
  transition: border-color 0.15s, box-shadow 0.15s;
  outline: none;
}

.input-primary::placeholder {
  color: #a8a29e;
}

.input-primary:focus {
  border-color: var(--mealy-orange);
  box-shadow: 0 0 0 3px rgba(249, 115, 22, 0.15);
}

.input-primary.input-error {
  border-color: var(--mealy-error);
}

/* ── Error message ────────────────────────────────────────── */
.field-error {
  font-size: 0.78rem;
  color: var(--mealy-error);
}

.auth-error-banner {
  background: var(--mealy-error-bg);
  border: 1px solid #fca5a5;
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 0.85rem;
  color: var(--mealy-error);
  display: flex;
  align-items: center;
  gap: 8px;
}

/* ── Button ───────────────────────────────────────────────── */
.btn-primary {
  width: 100%;
  padding: 11px;
  background: var(--mealy-orange);
  color: #fff;
  border: none;
  border-radius: 8px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  margin-top: 4px;
}

.btn-primary:hover:not(:disabled) {
  background: var(--mealy-orange-hover);
}

.btn-primary:active:not(:disabled) {
  transform: scale(0.98);
}

.btn-primary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* ── Footer link ──────────────────────────────────────────── */
.auth-footer {
  text-align: center;
  font-size: 0.85rem;
  color: var(--mealy-muted);
  margin-top: 20px;
}

.auth-footer a {
  color: var(--mealy-orange);
  font-weight: 600;
  text-decoration: none;
}

.auth-footer a:hover {
  text-decoration: underline;
}

/* ── Spinner ──────────────────────────────────────────────── */
.spinner {
  display: inline-block;
  width: 16px;
  height: 16px;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
  vertical-align: middle;
  margin-right: 6px;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* ── Responsive ───────────────────────────────────────────── */
@media (max-width: 480px) {
  .auth-card {
    padding: 28px 20px;
  }
  .auth-row {
    grid-template-columns: 1fr;
  }
}

import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../../context/AuthContext";
import "../auth.css";

function SignupCard() {
  const { signup, isLoading, error, clearError } = useAuth();
  const navigate = useNavigate();

  const [form, setForm] = useState({
    username: "",
    email: "",
    password: "",
    confirmPassword: "",
  });
  const [fieldErrors, setFieldErrors] = useState({});

  function handleChange(e) {
    clearError();
    setFieldErrors((prev) => ({ ...prev, [e.target.name]: "" }));
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  }

  function validate() {
    const errors = {};
    if (!form.username.trim()) errors.username = "Username required.";
    if (!form.email.trim()) errors.email = "Email required.";
    else if (!/\S+@\S+\.\S+/.test(form.email)) errors.email = "Invalid email.";
    if (!form.password) errors.password = "Password required.";
    else if (form.password.length < 6) errors.password = "Min 6 characters.";
    if (form.password !== form.confirmPassword)
      errors.confirmPassword = "Passwords do not match.";
    return errors;
  }

  async function handleSubmit(e) {
    e.preventDefault();
    const errors = validate();
    if (Object.keys(errors).length) {
      setFieldErrors(errors);
      return;
    }
    const result = await signup(form);
    if (result.success) navigate("/menu");
  }

  return (
    <div className="auth-page">
      <div className="auth-card">
        {/* Logo */}
        <div className="auth-logo">
          <img
            src="https://res.cloudinary.com/diwkfbsgv/image/upload/v1775206748/logo_u4sz9t.svg"
            alt="Mealy logo"
          />
        </div>

        <h1 className="auth-heading">Create your account</h1>
        <p className="auth-subtext">Set up your workspace in under a minute.</p>

        {/* API-level error banner */}
        {error && (
          <div className="auth-error-banner" role="alert">
            <span>⚠</span> {error}
          </div>
        )}

        <form className="auth-form" onSubmit={handleSubmit} noValidate>
          {/* Row 1: username + email */}
          <div className="auth-row">
            <div className="auth-field">
              <label htmlFor="username">Username</label>
              <input
                id="username"
                name="username"
                autoComplete="username"
                placeholder="zawadi"
                className={`input-primary${fieldErrors.username ? " input-error" : ""}`}
                value={form.username}
                onChange={handleChange}
              />
              {fieldErrors.username && (
                <span className="field-error">{fieldErrors.username}</span>
              )}
            </div>

            <div className="auth-field">
              <label htmlFor="email">Email</label>
              <input
                id="email"
                name="email"
                type="email"
                autoComplete="email"
                placeholder="zawadi@company.com"
                className={`input-primary${fieldErrors.email ? " input-error" : ""}`}
                value={form.email}
                onChange={handleChange}
              />
              {fieldErrors.email && (
                <span className="field-error">{fieldErrors.email}</span>
              )}
            </div>
          </div>

          {/* Row 2: password + confirm */}
          <div className="auth-row">
            <div className="auth-field">
              <label htmlFor="password">Password</label>
              <input
                id="password"
                name="password"
                type="password"
                autoComplete="new-password"
                placeholder="Password"
                className={`input-primary${fieldErrors.password ? " input-error" : ""}`}
                value={form.password}
                onChange={handleChange}
              />
              {fieldErrors.password && (
                <span className="field-error">{fieldErrors.password}</span>
              )}
            </div>

            <div className="auth-field">
              <label htmlFor="confirmPassword">Confirm password</label>
              <input
                id="confirmPassword"
                name="confirmPassword"
                type="password"
                autoComplete="new-password"
                placeholder="Confirm password"
                className={`input-primary${fieldErrors.confirmPassword ? " input-error" : ""}`}
                value={form.confirmPassword}
                onChange={handleChange}
              />
              {fieldErrors.confirmPassword && (
                <span className="field-error">{fieldErrors.confirmPassword}</span>
              )}
            </div>
          </div>

          <button type="submit" className="btn-primary" disabled={isLoading}>
            {isLoading && <span className="spinner" />}
            {isLoading ? "Creating account…" : "Create account"}
          </button>
        </form>

        <p className="auth-footer">
          Already have an account? <Link to="/login">Log in</Link>
        </p>
      </div>
    </div>
  );
}

export default SignupCard;

